package br.ben10.rhythm;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.media.projection.MediaProjectionManager;import android.Manifest;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.net.*;import java.io.*;
public final class MainActivity extends Activity {
 private TextView status;private EditText code,port;private Button connect;private Spinner musicApp;private CheckBox shared;private java.util.ArrayList<Integer> appUids=new java.util.ArrayList<>();private String token;private int gamePort=3000;private boolean registered;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){status.setText(i.getStringExtra("text"));}};
 public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(13,35,30));getWindow().setNavigationBarColor(Color.rgb(13,35,30));
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,48,28,28);root.setBackgroundColor(Color.rgb(13,35,30));ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);
  text(root,"BATIDA OMNITRIX",27);text(root,"Música de outro app → dança da LIVE",17);text(root,"1. Deixe o jogo no Termux ligado.\n2. No jogo, abra ♫ PHONK e gere um código.\n3. Digite o código e permita o acesso de áudio.\n4. Toque a música e volte para o jogo.",16);
  code=new EditText(this);code.setHint("Código de 6 números do jogo");code.setInputType(2);code.setTextColor(Color.WHITE);code.setHintTextColor(Color.LTGRAY);root.addView(code);
  port=new EditText(this);port.setHint("Porta do jogo");port.setInputType(2);port.setText("3000");port.setTextColor(Color.WHITE);root.addView(port);
  shared=new CheckBox(this);shared.setText("Captura compartilhada avançada (pode parar outra gravação/LIVE)");shared.setTextColor(Color.LTGRAY);shared.setChecked(false);root.addView(shared);
  text(root,"Filtro do app da música (somente na captura compartilhada)",15);musicApp=new Spinner(this);java.util.ArrayList<String> names=new java.util.ArrayList<>();names.add("Mídia de todos os aplicativos");appUids.add(-1);java.util.List<android.content.pm.ResolveInfo> apps=getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);java.util.Collections.sort(apps,new android.content.pm.ResolveInfo.DisplayNameComparator(getPackageManager()));java.util.HashSet<Integer> seen=new java.util.HashSet<>();for(android.content.pm.ResolveInfo a:apps){int uid=a.activityInfo.applicationInfo.uid;if(uid==android.os.Process.myUid()||!seen.add(uid))continue;names.add(a.loadLabel(getPackageManager()).toString());appUids.add(uid);}musicApp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));root.addView(musicApp);musicApp.setEnabled(false);shared.setOnCheckedChangeListener((b,checked)->musicApp.setEnabled(checked));
  connect=new Button(this);connect.setText("Conectar e captar a batida");connect.setOnClickListener(v->pair());root.addView(connect);
  Button stop=new Button(this);stop.setText("Parar captura");stop.setOnClickListener(v->{startService(new Intent(this,CaptureService.class).setAction("STOP"));status.setText("Captura encerrada.");});root.addView(stop);
  status=text(root,"Pronto para conectar.",17);
  text(root,"Envia somente níveis de energia para 127.0.0.1 no próprio celular. Não grava música, não envia PCM e não usa um servidor externo. O microfone não é ligado.",14);
  text(root,"O modo padrão tenta analisar a saída de áudio sem iniciar outra captura de tela. Alguns aparelhos, saídas Bluetooth ou aplicativos não fornecem esse sinal. Nesse caso, use o player do jogo ou BPM manual. A captura compartilhada é opcional e pode disputar a captura de tela da LIVE; não é ativada automaticamente.",14);
 }
 private TextView text(LinearLayout root,String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(220,245,207));t.setPadding(0,12,0,18);root.addView(t);return t;}
 protected void onResume(){super.onResume();IntentFilter filter=new IntentFilter(CaptureService.STATUS);if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,filter);registered=true;}
 protected void onPause(){if(registered){unregisterReceiver(receiver);registered=false;}super.onPause();}
 private void pair(){try{gamePort=Integer.parseInt(port.getText().toString());if(gamePort<1024||gamePort>65535)throw new Exception();}catch(Exception e){status.setText("Porta inválida.");return;}String c=code.getText().toString().trim();if(!c.matches("[0-9]{6}")){status.setText("Digite os seis números gerados no jogo.");return;}
  stopService(new Intent(this,CaptureService.class));connect.setEnabled(false);status.setText("Conectando ao jogo local…");new Thread(()->{try{String body="{\"code\":\""+c+"\"}";HttpURLConnection q=(HttpURLConnection)new URL("http://127.0.0.1:"+gamePort+"/api/rhythm/pair").openConnection();q.setRequestMethod("POST");q.setConnectTimeout(2000);q.setReadTimeout(2000);q.setRequestProperty("Content-Type","application/json");q.setDoOutput(true);try(OutputStream out=q.getOutputStream()){out.write(body.getBytes("UTF-8"));}int result=q.getResponseCode();InputStream in=result==200?q.getInputStream():q.getErrorStream();ByteArrayOutputStream b=new ByteArrayOutputStream();if(in!=null){byte[] buffer=new byte[512];int n;while((n=in.read(buffer))>0&&b.size()<4096)b.write(buffer,0,n);in.close();}JSONObject reply=new JSONObject(b.toString("UTF-8"));if(result!=200)throw new Exception(reply.optString("error","Código recusado"));token=reply.getString("token");runOnUiThread(()->{connect.setEnabled(true);permission();});}catch(Exception e){runOnUiThread(()->{connect.setEnabled(true);status.setText("Não conectou: "+e.getMessage()+". Confira o jogo e gere outro código.");});}},"omni-pair").start();
 }
 private void permission(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},41);return;}chooseCapture();}
 public void onRequestPermissionsResult(int r,String[] p,int[] grants){super.onRequestPermissionsResult(r,p,grants);if(r==41){if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)chooseCapture();else status.setText("Sem permissão de áudio. A captura não começou.");}}
 private void chooseCapture(){if(!shared.isChecked()){launchCapture(0,null,false);return;}new AlertDialog.Builder(this).setTitle("Captura compartilhada").setMessage("Uma nova captura no Android pode parar uma LIVE ou gravação que esteja compartilhando a tela. Não use esta opção durante esse tipo de transmissão. O modo padrão não abre essa captura.").setNegativeButton("Cancelar",(d,w)->status.setText("Captura compartilhada cancelada.")).setPositiveButton("Continuar",(d,w)->projection()).show();}
 private void projection(){MediaProjectionManager manager=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(manager.createScreenCaptureIntent(),42);}
 private void launchCapture(int result,Intent data,boolean share){try{Intent i=new Intent(this,CaptureService.class).putExtra("result",result).putExtra("projection",data).putExtra("shared",share).putExtra("token",token).putExtra("port",gamePort).putExtra("musicUid",appUids.get(musicApp.getSelectedItemPosition()));startForegroundService(i);status.setText(share?"Iniciando captura compartilhada… volte ao jogo.":"Iniciando análise de saída, sem nova captura de tela… volte ao jogo.");}catch(Exception e){status.setText("Não iniciou: "+e.getMessage());}}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==42){if(result!=RESULT_OK||data==null){status.setText("Compartilhamento cancelado. Nada foi capturado.");return;}launchCapture(result,data,true);}}
}
